1	import type { RequestHandler } from "@builder.io/qwik-city";
2	
3	/**
4	 * Stable per-platform desktop download links.
5	 *
6	 * Served at `/download/macos`, `/download/windows`, `/download/linux`. CI
7	 * publishes versioned assets (e.g. `twyne-desktop-macos-1.4.2.tar.gz`) to the
8	 * latest GitHub release, so there is no fixed file URL to hardcode. This
9	 * endpoint asks the GitHub API for the latest release, finds the asset whose
10	 * name starts with `twyne-desktop-<platform>`, and 302-redirects to it.
11	 *
12	 * On any miss (unknown platform, no matching asset, API failure) it falls back
13	 * to the human releases page rather than erroring, so a button always lands
14	 * somewhere useful.
15	 */
16	
17	const REPO = "Diogenesoftoronto/twyne";
18	const RELEASES_PAGE = `https://github.com/${REPO}/releases/latest`;
19	const LATEST_API = `https://api.github.com/repos/${REPO}/releases/latest`;
20	
21	/** Normalise common aliases to the asset-name platform token. */
22	const PLATFORM_ALIASES: Record<string, "macos" | "windows" | "linux"> = {
23	  macos: "macos",
24	  mac: "macos",
25	  osx: "macos",
26	  darwin: "macos",
27	  apple: "macos",
28	  windows: "windows",
29	  win: "windows",
30	  win64: "windows",
31	  linux: "linux",
32	};
33	
34	interface GitHubAsset {
35	  name: string;
36	  browser_download_url: string;
37	}
38	
39	export const onGet: RequestHandler = async ({ params, redirect, headers }) => {
40	  // Let CDNs/browsers cache the redirect briefly so we don't hammer GitHub's
41	  // unauthenticated rate limit (60 req/hr) on every button click.
42	  headers.set("Cache-Control", "public, max-age=900, s-maxage=900");
43	
44	  const platform = PLATFORM_ALIASES[(params.platform ?? "").toLowerCase()];
45	
46	  // Resolve the asset URL first; only throw the redirect once, afterwards, so
47	  // Qwik City's thrown-redirect control flow isn't caught by our own try/catch.
48	  let target = RELEASES_PAGE;
49	  if (platform) {
50	    try {
51	      const res = await fetch(LATEST_API, {
52	        headers: {
53	          Accept: "application/vnd.github+json",
54	          "User-Agent": "twyne-download-redirect",
55	        },
56	      });
57	      if (res.ok) {
58	        const release = (await res.json()) as { assets?: GitHubAsset[] };
59	        const prefix = `twyne-desktop-${platform}`;
60	        const asset = release.assets?.find((a) => a.name.startsWith(prefix));
61	        if (asset) {
62	          target = asset.browser_download_url;
63	        }
64	      }
65	    } catch {
66	      // Network/parse failure — fall back to the releases page below.
67	    }
68	  }
69	
70	  throw redirect(302, target);
71	};
