        0 1px 0 rgba(255, 255, 255, 0.6) inset,
        0 18px 34px -22px rgba(31, 27, 22, 0.5);
    }
    .dl-card-recommended {
      border-color: var(--color-vermilion);
      border-width: 2px;
      padding: calc(1.1rem - 1px) calc(1.1rem - 1px) calc(1.2rem - 1px);
    }
    .dl-stamp {
      position: absolute;
      top: -0.6rem;
      right: -0.6rem;
      width: 3.4rem;
      height: 3.4rem;
      opacity: 0;
      pointer-events: none;
      animation: dl-stamp-down 0.4s ease-out 0.05s forwards;
    }
    .dl-stamp-soon {
      opacity: 0.85;
      animation: none;
    }
    @keyframes dl-stamp-down {
      0% {
        opacity: 0;
        transform: scale(1.6) rotate(4deg);
      }
      70% {
        opacity: 1;
        transform: scale(0.92) rotate(4deg);
      }
      100% {
        opacity: 0.9;
        transform: scale(1) rotate(4deg);
      }
    }
    .dl-glyph {
      font-size: 1.6rem;
      line-height: 1;
    }
    .dl-name {
      font-family: var(--font-display);
      font-weight: 700;
      font-size: 1.15rem;
      color: var(--color-ink);
    }
    .dl-format {
      font-family: var(--font-typewriter);
      font-size: 0.62rem;
      text-transform: uppercase;
      letter-spacing: 0.14em;
      color: var(--color-ink-muted);
    }
    .dl-note {
      font-family: var(--font-serif);
      font-size: 0.85rem;
      line-height: 1.5;
      color: var(--color-ink-light);
      margin: 0;
      flex: 1 1 auto;
    }
    .dl-btn {
      align-self: flex-start;
      margin-top: 0.2rem;
      padding: 0.45rem 0.95rem;
      font-family: var(--font-display);
      font-weight: 600;
      font-size: 0.85rem;
      color: var(--color-paper-soft);
      background: var(--color-vermilion);
      border: 1px solid var(--color-vermilion-2);
      border-radius: 2px;
      text-decoration: none;
      cursor: pointer;
      transition: background 0.15s ease;
    }
    .dl-btn:hover {
      background: var(--color-vermilion-2);
    }
    .dl-btn:disabled {
      opacity: 0.6;
      cursor: default;
    }
    .dl-btn-small {
      font-size: 0.78rem;
      padding: 0.4rem 0.8rem;
      white-space: nowrap;
    }
    .dl-detect-line {
      min-height: 1.4rem;
      font-family: var(--font-typewriter);
      font-size: 0.72rem;
      letter-spacing: 0.08em;
      color: var(--color-ink-muted);
      margin: 0 0 0.6rem;
      opacity: 0;
      transition: opacity 0.4s ease;
    }
    .dl-detect-line.dl-detect-visible {
      opacity: 1;
    }
    .dl-detect-line strong {
      color: var(--color-vermilion);
    }
    .dl-benefits {
      list-style: none;
      margin: 0.5rem 0 1rem;
      padding: 0;
      display: grid;
      gap: 0.5rem;
    }
    .dl-benefits li {
      font-family: var(--font-serif);
      font-size: 0.9rem;
      line-height: 1.55;
      color: var(--color-ink-light);
      padding-left: 1.4rem;
      position: relative;
    }
    .dl-benefits li::before {
      content: "✦";
      position: absolute;
      left: 0;
      top: 0.05rem;
      color: var(--color-vermilion);
      font-size: 0.75rem;
    }
    .dl-web {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.9rem;
      padding: 1.1rem 1.2rem;
      background: var(--color-paper);
      border: 1px dashed var(--color-paper-3);
      border-radius: 3px;
    }
    .dl-web-body {
      flex: 1 1 16rem;
    }
    .dl-web-body p {
      margin: 0.3rem 0 0;
      font-family: var(--font-serif);
      font-size: 0.88rem;
      line-height: 1.55;
      color: var(--color-ink-light);
