1958	/* ── Draft text helpers ──────────────────────────────────────── */
1959	
1960	async function readCurrentDraftText(): Promise<string> {
1961	  let draftText = "";
1962	  const receive = (e: Event) => {
1963	    draftText = (e as CustomEvent).detail as string;
1964	  };
1965	  window.addEventListener("twyne:draft-text", receive);
1966	  window.dispatchEvent(new CustomEvent("twyne:request-draft"));
1967	  window.removeEventListener("twyne:draft-text", receive);
1968	  return draftText || (await loadDraftText());
1969	}
1970	
1971	/* ── Display helpers ────────────────────────────────────────── */
1972	
1973	function typeLabel(type: PersonaFeedback["type"]): string {
1974	  switch (type) {
1975	    case "encouragement":
1976	      return "in defense of";
1977	    case "suggestion":
1978	      return "a small suggestion";
1979	    case "critique":
1980	      return "a counter-reading";
1981	    case "perspective":
1982	      return "from the audience";
1983	  }
1984	}
1985	
1986	function truncate(text: string, n: number): string {
1987	  if (text.length <= n) return text;
1988	  return text.slice(0, n - 1).trimEnd() + "…";
1989	}
1990	
1991	function timeAgo(timestamp: number): string {
1992	  const seconds = Math.floor((Date.now() - timestamp) / 1000);
1993	  if (seconds < 60) return "just now";
1994	  const minutes = Math.floor(seconds / 60);
1995	  if (minutes < 60) return `${minutes}m`;
