   * the fallback when the numeric margins below are absent. New documents and
   * the layout sliders write the numeric fields instead.
   */
  margin: DocMargin;
  /** Side (left/right) page margin, in rem. Falls back to {@link margin} when undefined. */
  marginX?: number;

