10	import { renderMarkdown } from "../../utils/markdown";
11	
12	interface RubricPageStore {
13	  result: RubricResult | null;
14	  loaded: boolean;
15	}
16	
17	const GRADE_COLOR: Record<string, string> = {
18	  "A+": "var(--color-accent-green)",
19	  A: "var(--color-accent-green)",
20	  "A-": "var(--color-accent-green)",
21	  "B+": "var(--color-accent-blue)",
22	  B: "var(--color-accent-blue)",
23	  "B-": "var(--color-accent-blue)",
24	  "C+": "var(--color-accent-amber)",
25	  C: "var(--color-accent-amber)",
26	  "C-": "var(--color-accent-amber)",
27	  "D+": "var(--color-vermilion)",
28	  D: "var(--color-vermilion)",
29	  "D-": "var(--color-vermilion)",
30	  F: "var(--color-vermilion)",
31	};
32	
33	function scoreColor(score: number, max: number): string {
34	  const pct = score / max;
35	  if (pct >= 0.8) return "var(--color-accent-green)";
36	  if (pct >= 0.6) return "var(--color-accent-amber)";
37	  return "var(--color-accent-red)";
38	}
39	
40	function pct(n: number): number {
41	  return Math.round(n * 100);
42	}
43	
44	/** Concrete, prescriptive next step for a low-scoring criterion. */
45	function nextMoveFor(id: string): string {
46	  const moves: Record<string, string> = {
47	    thesis:
48	      "State the load-bearing claim in one sentence near the top, then make every section earn it.",
49	    evidence:
50	      "Pick the two weakest claims and attach a source, example, or number to each.",
51	    structure:
52	      "Add a section break or transition where the argument changes gears; cut a paragraph that repeats.",
53	    pacing:
54	      "Vary sentence length — break one long sentence in three, and merge two short ones.",
55	    voice:
56	      "Rewrite the opening line in the target tone; let it set the register for the rest.",
57	    vocabulary:
58	      "Replace three abstractions with concrete nouns; cut one piece of jargon per paragraph.",
59	    paragraph: "Split any paragraph over ~6 sentences; give each a single job.",
60	    engagement:
61	      "Put a stake or a question in the first 100 words so the reader knows why to continue.",
62	  };
63	  return (
64	    moves[id] ??
65	    "Make the one change that would most move this score, then re-read."
66	  );
67	}
68	
69	/** Static curve anchors for "the brutal curve" explainer. */
70	const CURVE_ANCHORS: Array<[number, number, string]> = [
71	  [50, 50, "A C-grade draft stays a C — Twyne does not flatter."],
72	  [
73	    60,
74	    58,
75	    "Above 60 the curve compresses — work that looks good still scores below its raw value.",
76	  ],
77	  [70, 67, "70 raw → 67 final. Most good drafts land here on first pass."],
78	  [
79	    80,
80	    76,
81	    "80 raw → 76. The curve is honest about the gap between polished and exemplary.",
82	  ],
83	  [90, 86, "90 raw → 86. You have to clear the 90 bar to land in the 80s."],
84	  [
85	    95,
86	    93,
87	    "Above 95 the curve stretches — only genuinely strong work gets here.",
88	  ],
89	  [100, 100, "100 raw → 100. A perfect draft."],
90	];
