92	export default component$(() => {
93	  const store = useStore<RubricPageStore>({ result: null, loaded: false });
94	
95	  // eslint-disable-next-line qwik/no-use-visible-task
96	  useVisibleTask$(async () => {
97	    const cached = await loadRubricResultFromIdb();
98	    if (cached) store.result = cached;
99	    store.loaded = true;
100	  });
101	
102	  useStylesScoped$(`
103	    .grade-circle {
104	      border-radius: 999px;
