116	      background: var(--color-paper);
117	      border-radius: 4px;
118	    }
119	    .bar {
120	      height: 4px;
121	      background: var(--color-paper-2);
122	      border-radius: 2px;
123	      overflow: hidden;
124	    }
125	    .bar > span {
126	      display: block;
127	      height: 100%;
128	    }
129	    .anchor {
130	      display: grid;
131	      grid-template-columns: 1fr 1fr;
132	      gap: 1rem;
133	      padding: 0.65rem 0.85rem;
134	      border-bottom: 1px dashed var(--color-paper-3);
135	    }
136	    .anchor:last-child { border-bottom: none; }
137	  `);
138	
139	  return (
140	    <div
141	      class="min-h-screen bg-[var(--color-paper-soft)] text-[var(--color-ink)]"
142	      style={{ fontFamily: "var(--font-serif)" }}
143	    >
144	      <div class="max-w-5xl mx-auto px-6 py-8">
145	        <div class="flex items-center justify-between mb-6">
146	          <div>
147	            <p
148	              class="dept-label mb-1"
149	              style={{ fontFamily: "var(--font-typewriter)" }}
150	            >
151	              Twyne
152	            </p>
153	            <h1
154	              style={{
155	                fontFamily: "var(--font-display)",
156	                fontWeight: 700,
157	                fontSize: "1.75rem",
158	                color: "var(--color-ink)",
159	              }}
160	            >
161	              The Galley Proof
162	            </h1>
163	            <p class="text-sm text-[var(--color-ink-light)] mt-1">
164	              The full breakdown — what the judges said, what the rubric
165	              counted, what to fix next.
166	            </p>
167	          </div>
168	          <Link
169	            href="/editor"
170	            class="btn-paper text-sm"
171	            style={{ fontFamily: "var(--font-display)" }}
172	          >
173	            ← Back to desk
174	          </Link>
175	        </div>
