const JUDGE_WEIGHT = 0.45;
const MIN_JUDGE_WEIGHT = 0.35;
const STATIC_WEIGHT = 0.2;

export function combineJudgesAndStatic(
  judges: JudgeResult[],
  staticScore: StaticScore,
  brief: { answers: { audience: string; goal: string } } | null,
