1	/**
2	 * Per-user sync functions. Every mutation and query is auth-gated to
3	 * the calling user — the server-side identity is the source of truth,
4	 * never an argument. This is the contract the Convex AI guidelines
5	 * require: "NEVER accept a userId or any user identifier as a function
6	 * argument for authorization purposes."
7	 *
8	 * The functions cover everything the browser used to keep in IndexedDB:
9	 *   • briefs         — project dossier
10	 *   • folios         — list of pieces
11	 *   • folioContent   — per-folio manuscript HTML
12	 *   • customPersonas — user-edited editorial board
13	 *   • personaNotes   — the room's marginalia
14	 *   • personaReplies — threaded reply chains on each note
15	 *   • rubricResults  — latest galley-proof result
16	 *   • bibliographies — saved citation/source entries
17	 *
18	 * For each table, a `getX` (read latest) and `putX` (upsert) is exposed.
19	 * `pullAll` and `pushAll` are bulk convenience wrappers used on sign-in
20	 * and sign-up to hydrate or seed the server in one round-trip.
21	 */
22	
23	import { mutation, query } from "./_generated/server";
24	import { v } from "convex/values";
25	
26	/* ── Identity helpers ───────────────────────────────────────────── */
27	
28	async function requireIdentity(ctx: {
29	  auth: { getUserIdentity: () => Promise<{ tokenIdentifier: string } | null> };
30	}): Promise<string> {
