/**$

src/routes/[handle]/index.tsx: JavaScript source, Unicode text, UTF-8 text
     1	/**
     2	 * The writer's public profile. Canonical URL: /<handle>
     3	 *
     4	 * Reverse-chronological list of the writer's published "post" pieces. The
     5	 * blog feed is separate (`/blog`), so a writer who is also an admin sees
     6	 * their admin-authored posts on `/blog`, and everything else they've
     7	 * published here.
     8	 *
     9	 * No auth. The profile (handle + display name + bio) is loaded first; the
    10	 * piece list follows. A missing handle renders the same shape as an empty
    11	 * profile, to avoid user enumeration.
    12	 */
    13	
    14	import { component$, useSignal, useVisibleTask$ } from "@builder.io/qwik";
    15	import { type DocumentHead, useLocation, Link } from "@builder.io/qwik-city";
    16	import { useConvexClient } from "../../utils/convex-context";
    17	import { api } from "../../../convex/_generated/api";
    18	
    19	interface Profile {
    20	  handle: string;
    21	  displayName: string | null;
    22	  bio: string | null;
    23	  avatarUrl: string | null;
    24	}
    25	
    26	interface PublishedSummary {
    27	  slug: string;
    28	  ownerHandle: string | null;
    29	  title: string;
    30	  briefSummary: string | null;
    31	  publishedAt: number;
    32	}
    33	
    34	export default component$(() => {
    35	  const loc = useLocation();
    36	  const clientSig = useConvexClient();
    37	  const profile = useSignal<Profile | null>(null);
    38	  const posts = useSignal<PublishedSummary[]>([]);
    39	  const isLoading = useSignal(true);
    40	  const missing = useSignal(false);
    41	
    42	  // eslint-disable-next-line qwik/no-use-visible-task
    43	  useVisibleTask$(async () => {
    44	    const handle = (loc.params.handle ?? "").toLowerCase();
    45	    const client = clientSig.value;
    46	    if (!client || !handle) {
    47	      isLoading.value = false;
    48	      return;
    49	    }
    50	    try {
    51	      const [profileData, postData] = await Promise.all([
    52	        client.query(api.profiles.getProfile, { handle }) as Promise<
    53	          Profile | null
    54	        >,
    55	        client.query(api.published.listByHandle, { handle }) as Promise<
    56	          PublishedSummary[]
    57	        >,
    58	      ]);
    59	      if (!profileData) {
    60	        missing.value = true;
    61	        isLoading.value = false;
    62	        return;
    63	      }
    64	      profile.value = profileData;
    65	      posts.value = postData;
    66	    } catch {
    67	      missing.value = true;
    68	    } finally {
    69	      isLoading.value = false;
    70	    }
    71	  });
    72	
    73	  const handle = (loc.params.handle ?? "").toLowerCase();
    74	
    75	  return (
    76	    <main class="min-h-screen bg-[var(--color-paper)] text-[var(--color-ink)]">
    77	      <header class="border-b border-[var(--color-paper-3)]">
    78	        <div class="mx-auto max-w-2xl px-6 pt-10 pb-8">
    79	          <p
    80	            class="text-[11px] tracking-[0.18em] uppercase text-[var(--color-ink-muted)] mb-2"
    81	            style="font-family: var(--font-typewriter);"
    82	          >
    83	            <Link
    84	              href="/"
    85	              class="hover:text-[var(--color-vermilion)]"
    86	            >
    87	              ← Twyne
    88	            </Link>
    89	          </p>
    90	          {isLoading.value && (
    91	            <p
    92	              class="text-sm text-[var(--color-ink-muted)]"
    93	              style="font-family: var(--font-typewriter); letter-spacing: 0.16em; text-transform: uppercase;"
    94	            >
    95	              Loading the desk…
    96	            </p>
    97	          )}
    98	          {missing.value && !isLoading.value && (
    99	            <>
   100	              <h1
   101	                class="text-3xl text-[var(--color-ink)]"
   102	                style="font-family: var(--font-display); font-weight: 700;"
   103	              >
   104	                No writer by that handle.
   105	              </h1>
   106	              <p
   107	                class="mt-2 text-sm text-[var(--color-ink-light)]"
   108	                style="font-family: var(--font-serif);"
   109	              >
   110	                If you arrived here from an old link, the writer may have
   111	                changed their handle.
   112	              </p>
   113	            </>
   114	          )}
   115	          {profile.value && (
   116	            <>
   117	              <div class="flex items-center gap-4">
   118	                {profile.value.avatarUrl && (
   119	                  <img
   120	                    src={profile.value.avatarUrl}
   121	                    alt={`${profile.value.displayName || profile.value.handle}'s profile picture`}
   122	                    width="64"
   123	                    height="64"
   124	                    class="h-16 w-16 flex-shrink-0 rounded-full border border-[var(--color-paper-3)] object-cover"
   125	                  />
   126	                )}
   127	                <h1
   128	                  class="text-3xl text-[var(--color-ink)]"
   129	                  style="font-family: var(--font-display); font-weight: 700;"
   130	                >
   131	                  {profile.value.displayName || `@${profile.value.handle}`}
   132	                </h1>
   133	              </div>
   134	              <p
   135	                class="mt-1 text-[11px] tracking-[0.18em] uppercase text-[var(--color-ink-muted)]"
   136	                style="font-family: var(--font-typewriter);"
   137	              >
   138	                twyne.love/{profile.value.handle}
   139	              </p>
   140	              {profile.value.bio && (
   141	                <p
   142	                  class="mt-3 text-base text-[var(--color-ink-light)] leading-relaxed"
   143	                  style="font-family: var(--font-serif);"
   144	                >
   145	                  {profile.value.bio}
   146	                </p>
   147	              )}
   148	            </>
   149	          )}
   150	        </div>
   151	      </header>
   152	
   153	      <div class="mx-auto max-w-2xl px-6 py-10">
   154	        {profile.value && posts.value.length === 0 && (
   155	          <p
   156	            class="text-sm text-[var(--color-ink-muted)] italic"
   157	            style="font-family: var(--font-serif);"
   158	          >
   159	            Nothing published yet.
   160	          </p>
   161	        )}
   162	        {posts.value.length > 0 && (
   163	          <ul class="space-y-8">
   164	            {posts.value.map((post) => (
   165	              <li key={post.slug}>
   166	                <p
   167	                  class="text-[10px] tracking-[0.2em] uppercase text-[var(--color-ink-muted)]"
   168	                  style="font-family: var(--font-typewriter);"
   169	                >
   170	                  {formatDate(post.publishedAt)}
   171	                </p>
   172	                <h2
   173	                  class="mt-1 text-2xl text-[var(--color-ink)]"
   174	                  style="font-family: var(--font-display); font-weight: 700;"
   175	                >
   176	                  <Link
   177	                    href={`/${handle}/${post.slug}`}
   178	                    class="hover:text-[var(--color-vermilion)]"
   179	                  >
   180	                    {post.title}
   181	                  </Link>
   182	                </h2>
   183	                {post.briefSummary && (
   184	                  <p
   185	                    class="mt-1 text-sm text-[var(--color-ink-light)] leading-relaxed"
   186	                    style="font-family: var(--font-serif);"
   187	                  >
   188	                    {post.briefSummary}
   189	                  </p>
   190	                )}
   191	              </li>
   192	            ))}
   193	          </ul>
   194	        )}
   195	      </div>
   196	    </main>
   197	  );
   198	});
   199	
   200	function formatDate(timestamp: number): string {
   201	  return new Date(timestamp).toLocaleDateString(undefined, {
   202	    year: "numeric",
   203	    month: "long",
   204	    day: "numeric",
   205	  });
   206	}
   207	
   208	export const head: DocumentHead = ({ params }) => ({
   209	  title: `Twyne · @${params.handle ?? "writer"}`,
   210	  meta: [
   211	    {
   212	      name: "description",
   213	      content: `Writing by @${params.handle ?? ""} on Twyne.`,
   214	    },
   215	    { property: "og:title", content: `Twyne · @${params.handle ?? "writer"}` },
   216	  ],
   217	});

