              class="hover:text-[var(--color-vermilion)]"
            >
              ← Twyne
            </Link>
          </p>
          {isLoading.value && (
            <p
              class="text-sm text-[var(--color-ink-muted)]"
              style="font-family: var(--font-typewriter); letter-spacing: 0.16em; text-transform: uppercase;"
            >
              Loading the desk…
            </p>
          )}
          {missing.value && !isLoading.value && (
            <>
              <h1
                class="text-3xl text-[var(--color-ink)]"
                style="font-family: var(--font-display); font-weight: 700;"
              >
                No writer by that handle.
              </h1>
              <p
                class="mt-2 text-sm text-[var(--color-ink-light)]"
                style="font-family: var(--font-serif);"
              >
                If you arrived here from an old link, the writer may have
                changed their handle.
              </p>
            </>
          )}
          {profile.value && (
            <>
              <div class="flex items-center gap-4">
                {profile.value.avatarUrl && (
                  <img
                    src={profile.value.avatarUrl}
                    alt={`${profile.value.displayName || profile.value.handle}'s profile picture`}
                    width="64"
                    height="64"
                    class="h-16 w-16 flex-shrink-0 rounded-full border border-[var(--color-paper-3)] object-cover"
                  />
                )}
                <h1
                  class="text-3xl text-[var(--color-ink)]"
                  style="font-family: var(--font-display); font-weight: 700;"
                >
                  {profile.value.displayName || `@${profile.value.handle}`}
                </h1>
              </div>
              <p
                class="mt-1 text-[11px] tracking-[0.18em] uppercase text-[var(--color-ink-muted)]"
                style="font-family: var(--font-typewriter);"
              >
                twyne.love/{profile.value.handle}
              </p>
              {profile.value.bio && (
                <p
                  class="mt-3 text-base text-[var(--color-ink-light)] leading-relaxed"
                  style="font-family: var(--font-serif);"
                >
                  {profile.value.bio}
                </p>
              )}
            </>
          )}
        </div>
      </header>

      <div class="mx-auto max-w-2xl px-6 py-10">
        {profile.value && posts.value.length === 0 && (
          <p
            class="text-sm text-[var(--color-ink-muted)] italic"
            style="font-family: var(--font-serif);"
          >
            Nothing published yet.
          </p>
        )}
        {posts.value.length > 0 && (
          <ul class="space-y-8">
            {posts.value.map((post) => (
              <li key={post.slug}>
                <p
                  class="text-[10px] tracking-[0.2em] uppercase text-[var(--color-ink-muted)]"
                  style="font-family: var(--font-typewriter);"
                >
                  {formatDate(post.publishedAt)}
                </p>
                <h2
                  class="mt-1 text-2xl text-[var(--color-ink)]"
                  style="font-family: var(--font-display); font-weight: 700;"
                >
                  <Link
                    href={`/${handle}/${post.slug}`}
                    class="hover:text-[var(--color-vermilion)]"
                  >
                    {post.title}
                  </Link>
                </h2>
                {post.briefSummary && (
                  <p
                    class="mt-1 text-sm text-[var(--color-ink-light)] leading-relaxed"
                    style="font-family: var(--font-serif);"
                  >
                    {post.briefSummary}
                  </p>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    </main>
  );
});

function formatDate(timestamp: number): string {
  return new Date(timestamp).toLocaleDateString(undefined, {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}

export const head: DocumentHead = ({ params }) => ({
  title: `Twyne · @${params.handle ?? "writer"}`,
  meta: [
    {
      name: "description",
      content: `Writing by @${params.handle ?? ""} on Twyne.`,
    },
    { property: "og:title", content: `Twyne · @${params.handle ?? "writer"}` },
  ],
});

/**
 * Per-day writing activity, for the public "days writing" heatmap on the
 * author profile page. `recordActivity` is called (throttled, client-side)
 * whenever the editor autosaves; `getPublicActivity` reads it back by handle
 * for anyone viewing that writer's profile — same "no userId argument"
 * auth contract as `convex/sync.ts`, since recording is always about the
 * calling user's own activity.
 */

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";
import { normalizeHandle } from "./profiles";
import { consumeRateLimit, RATE_LIMITS } from "./lib/rateLimit";

async function requireIdentity(ctx: {
  auth: { getUserIdentity: () => Promise<{ tokenIdentifier: string } | null> };
}): Promise<string> {
  const id = await ctx.auth.getUserIdentity();
  if (!id) throw new Error("Not signed in");
  return id.tokenIdentifier;
}

function todayUtc(): string {
  return new Date().toISOString().slice(0, 10);
}

export const recordActivity = mutation({
  args: {},
  handler: async (ctx, _args) => {
    const userId = await requireIdentity(ctx);
    await consumeRateLimit(ctx, {
      action: "writingActivity:record",
      identifier: userId,
      ...RATE_LIMITS.writingActivity,
    });

    const day = todayUtc();
    const now = Date.now();
    const existing = await ctx.db
      .query("writingActivity")
      .withIndex("by_userId_day", (q) =>
        q.eq("userId", userId).eq("day", day),
      )
      .unique();

    if (existing) {
      await ctx.db.patch(existing._id, {
        count: existing.count + 1,
        updatedAt: now,
      });
      return existing._id;
    }
    return await ctx.db.insert("writingActivity", {
      userId,
      day,
      count: 1,
      updatedAt: now,
    });
  },
});

export const getPublicActivity = query({
  args: { handle: v.string() },
  handler: async (ctx, { handle }) => {
    const normalized = normalizeHandle(handle);
    const handleRow = await ctx.db
      .query("handles")
      .withIndex("by_handle", (q) => q.eq("handle", normalized))
      .unique();
    if (!handleRow) return null;

    const userId = handleRow.userId;
    const days = await ctx.db
      .query("writingActivity")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .collect();

    const folioRow = await ctx.db
      .query("folios")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .first();
    const folioCount = Array.isArray(folioRow?.folios)
      ? folioRow.folios.length
      : 0;

    return {
      days: days.map((d) => ({ day: d.day, count: d.count })),
      folioCount,
    };
  },
});

